import React, {useMemo, useState} from "react";
import {Button, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle} from "@mui/material";
import {GridActionsCellItem, GridColDef, GridRowParams} from "@mui/x-data-grid";
import EditOutlinedIcon from "@mui/icons-material/EditOutlined";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import AddIcon from "@mui/icons-material/Add";
import {NavLink, useNavigate} from "react-router-dom";
import {toast} from "react-toastify";
import {CategoryType} from "../../models/category";
import {CatalogGenerationBatch, CatalogGenerationJobStatus} from "../../models/catalogGeneration";
import {
    useDeleteCatalogGenerationBatchMutation,
    useGetCatalogGenerationBatchesQuery,
} from "./catalogGenerationApi";
import {useTranslation} from "../../i18n";
import {getApiErrorMessage} from "../../api/errors";
import {useAppDispatch} from "../../store/store";
import {productsApi} from "../products/productsApi";
import {servicesApi} from "../services/servicesApi";
import {stockApi} from "../stock/stockApi";
import Loader from "../../ui/loader/loader";
import CoreButton from "../../ui/buttons/coreButton";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    StyledDataGrid,
    Surface,
} from "../../ui/commonStyled/commonStyled";

const CatalogGenerationBatchesPage = () => {
    const {t, language} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useAppDispatch();
    const {data: batches = [], isLoading, isFetching} = useGetCatalogGenerationBatchesQuery(undefined, {
        pollingInterval: 3000,
    });
    const [deleteBatch, {isLoading: isDeleting}] = useDeleteCatalogGenerationBatchMutation();
    const [batchToDelete, setBatchToDelete] = useState<CatalogGenerationBatch>();

    const statusLabels = useMemo<Record<CatalogGenerationJobStatus, string>>(() => ({
        [CatalogGenerationJobStatus.Pending]: t("Pending"),
        [CatalogGenerationJobStatus.Running]: t("Running"),
        [CatalogGenerationJobStatus.Completed]: t("Completed"),
        [CatalogGenerationJobStatus.Failed]: t("Failed"),
        [CatalogGenerationJobStatus.Cancelled]: t("Cancelled"),
    }), [t]);
    const columns = useMemo<GridColDef[]>(() => [
        {field: "name", headerName: t("Batch name"), minWidth: 210, flex: 1},
        {field: "baseItemName", headerName: t("Base product or service"), minWidth: 200, flex: 1},
        {
            field: "itemType",
            headerName: t("Type"),
            width: 120,
            valueFormatter: ({value}) => value === CategoryType.Product ? t("Product") : t("Service"),
        },
        {
            field: "status",
            headerName: t("Status"),
            width: 140,
            valueFormatter: ({value}) => statusLabels[value as CatalogGenerationJobStatus] ?? String(value),
        },
        {field: "created", headerName: t("Created items"), type: "number", width: 125},
        {field: "total", headerName: t("Planned items"), type: "number", width: 125},
        {
            field: "createdAt",
            headerName: t("Created"),
            width: 180,
            valueFormatter: ({value}) => new Intl.DateTimeFormat(language, {
                dateStyle: "short",
                timeStyle: "short",
            }).format(new Date(value)),
        },
        {
            field: "actions",
            type: "actions",
            headerName: t("Actions"),
            width: 110,
            getActions: (params: GridRowParams<CatalogGenerationBatch>) => [
                <GridActionsCellItem
                    key="edit"
                    icon={<EditOutlinedIcon/>}
                    label={t("Edit batch")}
                    disabled={params.row.status === CatalogGenerationJobStatus.Pending || params.row.status === CatalogGenerationJobStatus.Running}
                    onClick={() => navigate(`/catalogGeneration?editBatchId=${params.row.id}`)}
                />,
                <GridActionsCellItem
                    key="delete"
                    icon={<DeleteOutlineIcon/>}
                    label={t("Delete batch")}
                    onClick={() => setBatchToDelete(params.row)}
                />,
            ],
        },
    ], [language, navigate, statusLabels, t]);

    const confirmDelete = async () => {
        if (!batchToDelete) return;
        try {
            const result = await deleteBatch(batchToDelete.id).unwrap();
            toast.success(t("Deleted products: {products}; services: {services}", {
                products: result.deletedProducts,
                services: result.deletedServices,
            }));
            dispatch(productsApi.util.invalidateTags(["Products", "Product"]));
            dispatch(servicesApi.util.invalidateTags(["Services", "Service"]));
            dispatch(stockApi.util.invalidateTags(["Stock"]));
            setBatchToDelete(undefined);
        } catch (error) {
            toast.error(getApiErrorMessage(error, t("Generation batch could not be deleted.")));
        }
    };

    if (isLoading) return <Loader/>;

    return (
        <MainDiv>
            <Dialog open={Boolean(batchToDelete)} onClose={() => !isDeleting && setBatchToDelete(undefined)}>
                <DialogTitle>{t("Delete generation batch?")}</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        {t("All products and services created by batch {name} will be removed from the catalog.", {
                            name: batchToDelete?.name,
                        })}
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button disabled={isDeleting} onClick={() => setBatchToDelete(undefined)}>{t("Cancel")}</Button>
                    <Button disabled={isDeleting} color="error" onClick={confirmDelete}>{t("Delete")}</Button>
                </DialogActions>
            </Dialog>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Generation batches")}</PageTitle>
                    <PageSubtitle>{t("Generated catalog groups, their progress, editing, and complete removal.")}</PageSubtitle>
                </PageTitleGroup>
                <NavLink to="/catalogGeneration" style={{textDecoration: "none"}}>
                    <CoreButton muiType="success" text={t("Create generation batch")} leftIcon={<AddIcon/>}/>
                </NavLink>
            </PageHeader>
            <Surface>
                <StyledDataGrid
                    autoHeight
                    rows={batches}
                    columns={columns}
                    loading={isFetching}
                    pageSizeOptions={[25, 50, 100]}
                    initialState={{pagination: {paginationModel: {pageSize: 25, page: 0}}}}
                    disableRowSelectionOnClick
                />
            </Surface>
        </MainDiv>
    );
};

export default CatalogGenerationBatchesPage;
